actions.script:
const repostResults = []
for (const invoice of Array.from(invoiceList)) {
    ec.message.pushErrors()
    try {
        ec.service.sync().name('mantle.ledger.InvoiceAutoPostServices.repost#Invoice')
            .parameters({invoiceId:invoice.invoiceId}).requireNewTransaction(true).throwOnError(true).call()
        if (ec.message.hasError()) throw new Error(ec.message.getErrorsString())
        repostResults.push({invoiceId:invoice.invoiceId,status:'complete'})
    } catch (error) {
        ec.logger.error('Invoice ' + invoice.invoiceId + ' repost failed: ' + error.message)
        repostResults.push({invoiceId:invoice.invoiceId,status:'failed',errorMessage:String(error.message)})
    } finally {
        ec.message.clearErrors()
        ec.message.popErrors()
    }
}
context.repostResults = repostResults
